-- Phase 4: academics, classes, sections, subjects and configurable curriculum
create table if not exists public.academic_classes(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,name text not null,code text not null,level_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_id,code));
create table if not exists public.sections(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,class_id uuid not null references public.academic_classes(id) on delete cascade,name text not null,code text not null,capacity integer,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(class_id,code));
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,name text not null,code text not null,subject_type text not null default 'general' check(subject_type in ('general','dars-e-nizami','quran','hadith','fiqh','arabic','urdu','english','other')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_id,code));
create table if not exists public.class_subjects(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,class_id uuid not null references public.academic_classes(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete cascade,weekly_periods integer not null default 1,is_core boolean not null default true,created_at timestamptz not null default now(),unique(class_id,subject_id));
create table if not exists public.curriculum_units(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,class_id uuid not null references public.academic_classes(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete cascade,title text not null,unit_order integer not null default 0,description text,reference_book text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists academic_classes_institution_idx on public.academic_classes(institution_id);
create index if not exists sections_class_idx on public.sections(class_id);
create index if not exists sections_institution_idx on public.sections(institution_id);
create index if not exists subjects_institution_type_idx on public.subjects(institution_id,subject_type);
create index if not exists class_subjects_class_idx on public.class_subjects(class_id);
create index if not exists class_subjects_subject_idx on public.class_subjects(subject_id);
create index if not exists curriculum_units_class_subject_idx on public.curriculum_units(class_id,subject_id);
create index if not exists class_subjects_institution_idx on public.class_subjects(institution_id);
create index if not exists curriculum_units_institution_idx on public.curriculum_units(institution_id);
create index if not exists curriculum_units_subject_idx on public.curriculum_units(subject_id);
alter table public.academic_classes enable row level security; alter table public.sections enable row level security; alter table public.subjects enable row level security; alter table public.class_subjects enable row level security; alter table public.curriculum_units enable row level security;
create policy academic_classes_select on public.academic_classes for select to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('academics.view')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy academic_classes_insert on public.academic_classes for insert to authenticated with check ((select app_private.is_super_admin()) or ((select app_private.has_permission('academics.edit')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
